def count_divisors(n):
    if n == 1:
        return 1
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            # If divisors are equal (i*i = n), count it once
            if i * i == n:
                count += 1
            # Otherwise count both i and n/i
            else:
                count += 2
    return count

